#!/usr/bin/env bash
set -euo pipefail
umask 077

PAYLOAD_SHA256='73feb3b7c43b425456dab48dd3fd1a7872e071b71ca25659f26b4ae673fe7a6d'
PAYLOAD_GZ_B64=''
export PAYLOAD_SHA256 PAYLOAD_GZ_B64

python - <<'PY' | bash -s -- "$@"
import base64
import gzip
import hashlib
import os
import re
import sys

raw = os.environ['PAYLOAD_GZ_B64']
clean = re.sub(r'[^A-Za-z0-9+/=]', '', raw)
decoded = gzip.decompress(base64.b64decode(clean, validate=False))
observed = hashlib.sha256(decoded).hexdigest()
expected = os.environ['PAYLOAD_SHA256']
if observed != expected:
    raise SystemExit(f'Cleanup preflight payload hash mismatch: {observed}')
sys.stdout.buffer.write(decoded)
PY
